head.b:skin:
/* 
THEME: Academic Blueprint (Navy & Chalk)
SYSTEM: Indonesia National English Curriculum Framework
*/
:root {
    --edu-navy: #1e3a8a;
    --edu-sky: #3b82f6;
    --chalk-white: #ffffff;
    --paper-edge: #e2e8f0;
    --sidebar-gold: #f59e0b;
}
body {
    background-color: #f8fafc;
    color: #334155;
    font-family: 'Inter', sans-serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: var(--edu-navy);
    color: white;
    padding: 50px 20px;
    text-align: center;
    border-bottom: 6px solid var(--edu-sky);
}
.header-wrap h1 { font-weight: 900; letter-spacing: 1px; margin: 0; }
.main-container {
    max-width: 950px;
    margin: -30px auto 60px;
    padding: 20px;
}
.edu-card {
    background: white;
    border-radius: 12px;
    padding: 40px;
    border: 1px solid var(--paper-edge);
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: 800;
    margin-bottom: 8px;
    color: var(--edu-navy);
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.input-group input, .input-group textarea, .input-group select {
    width: 100%;
    padding: 12px;
    border: 2px solid var(--paper-edge);
    border-radius: 8px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fff;
    font-size: 14px;
}
.input-group select { border-left: 6px solid var(--edu-sky); cursor: pointer; }

.flex-row { display: flex; gap: 15px; flex-wrap: wrap; }
.flex-item { flex: 1; min-width: 200px; }

h2 { border-left: 5px solid var(--sidebar-gold); padding-left: 15px; font-size: 20px; color: var(--edu-navy); }

.copy-btn {
    background: var(--edu-navy);
    color: white;
    border: none;
    padding: 20px;
    cursor: pointer;
    font-weight: 800;
    width: 100%;
    border-radius: 8px;
    transition: 0.3s;
    font-size: 15px;
    text-transform: uppercase;
}
.copy-btn:hover { background: var(--edu-sky); }
footer { text-align: center; color: #94a3b8; padding: 40px; font-size: 11px; text-transform: uppercase; }

body.script:
function copyPrompt() {
    var topic = document.getElementById("inputTopic").value || "English Basics";
    var notes = document.getElementById("inputNotes").value || "Focus on clarity and student engagement.";
    var level = document.getElementById("inputLevel").value;
    var format = document.getElementById("inputFormat").value;

    var template = document.getElementById("templateID").innerText;

    var finalPrompt = template
        .replace("[USER_TOPIC]", topic)
        .replace("[USER_NOTES]", notes)
        .replace(/\[USER_LEVEL\]/g, level)
        .replace(/\[USER_FORMAT\]/g, format);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("🍎 Education Prompt Copied! [Level: " + level.split('(')[0] + "]");
}
